ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/safeboot|recoveryenabled|bootstatuspolicy/i)
  OR (ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete\s+shadows/i)
  OR (ImageFileName=/\\wbadmin\.exe$/i AND CommandLine=/delete\s+catalog/i)
| case {
    CommandLine=/safeboot/i                                | Action := "bcd_safeboot" ;
    CommandLine=/recoveryenabled|bootstatuspolicy/i        | Action := "bcd_disable_recovery" ;
    ImageFileName=/vssadmin\.exe$/i                        | Action := "vss_wipe" ;
    ImageFileName=/wbadmin\.exe$/i                         | Action := "wbadmin_wipe" ;
    *                                                      | Action := "other" ;
  }
| groupBy([aid, ComputerName, UserName], function=[collect([Action, CommandLine]), count(field=Action, distinct=true, as=distinctActions), min(@timestamp, as=firstSeen), max(@timestamp, as=lastSeen)])
| distinctActions >= 2
